def transform(grid):
    # The figures are separated nonzero components; select the one using
    # three colors, while the distractors use only two.
    seen = set()
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            colors = {grid[y][x] for y, x in cells}
            if len(colors) == 3:
                y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
                x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
                return [row[x0:x1+1] for row in grid[y0:y1+1]]
    return []
